(6481316, 962716, 41142, '<td valign="top">Christophe I don''t want to sound too mawkish but you are really the only photographer I''ve seen here on dpchallenge who consistently (and spectacularly) excel across all genres. Congratulations for the nth time! :D</td>', 'Christophe I don''t want to sound too mawkish but you are really the only photographer I''ve seen here on dpchallenge who consistently (and spectacularly) excel across all genres. Congratulations for the nth time! :D', '2011-07-26 03:03:41.000000', NULL, 0),
(6481340, 962716, 114969, '<td valign="top">Thanks for these very kind comments!<br/> <br/>However there are many genres in which I did not produce any decent photo so far (and will likely never in several of them):<br/>- Street photography<br/>- City architecture<br/>- Impressionism<br/>- Wildlife<br/>- Documentary<br/>etc.<br/> <br/>Moreover, I''m well aware that some dislike very much the style of work I do for various reasons, so "excel" is always subjective word. But thanks a lot anyway, I am always very thrilled when my work is appreciated :-)<br/> <br/></td>', 'Thanks for these very kind comments! However there are many genres in which I did not produce any decent photo so far (and will likely never in several of them):- Street photography- City architecture- Impressionism- Wildlife- Documentaryetc. Moreover, I''m well aware that some dislike very much the style of work I do for various reasons, so "excel" is always subjective word. But thanks a lot anyway, I am always very thrilled when my work is appreciated :-) ', '2011-07-26 05:33:57.000000', NULL, 0),
(6481381, 962716, 59737, '<td valign="top">Amazing photo Christophe the colors are mesmerizing, almost looks like it''s moving</td>', 'Amazing photo Christophe the colors are mesmerizing, almost looks like it''s moving', '2011-07-26 09:11:50.000000', NULL, 0),
(6481384, 962636, 59737, '<td valign="top">simple elegant and tranquil, nice to see another one of your images here, I''ve admired your pictures for a while</td>', 'simple elegant and tranquil, nice to see another one of your images here, I''ve admired your pictures for a while', '2011-07-26 09:32:05.000000', NULL, 0),
(6481396, 962826, 64446, '<td valign="top">Another outstanding image of your! Congratulations on your ribbon.</td>', 'Another outstanding image of your! Congratulations on your ribbon.', '2011-07-26 10:18:15.000000', NULL, 0),
(6481409, 962071, 117474, '<td valign="top">Loved this. thought it should have done much better!</td>', 'Loved this. thought it should have done much better!', '2011-07-26 10:49:28.000000', NULL, 0),
(6481464, 962826, 96751, '<td valign="top">This is a class of photography that is so beyond my skills, I''m not even tempted to try.  I''d just rather sit here and admire this exquisiteness.  Yes, drops have been done.  But so have portraits, landscapes, etc. etc.  Besides, there are drops, and then there are DROPS!  Although I also wish the entire ripple could be seen, it''s an insignificant detail, compared to the complexity of colors you have achieved in both the subjects and their reflections, and the delicious smoothness of the green water.  Simply sensational.</td>', 'This is a class of photography that is so beyond my skills, I''m not even tempted to try.  I''d just rather sit here and admire this exquisiteness.  Yes, drops have been done.  But so have portraits, landscapes, etc. etc.  Besides, there are drops, and then there are DROPS!  Although I also wish the entire ripple could be seen, it''s an insignificant detail, compared to the complexity of colors you have achieved in both the subjects and their reflections, and the delicious smoothness of the green water.  Simply sensational.', '2011-07-26 13:01:53.000000', NULL, 0),
(6481465, 962357, 96751, '<td valign="top">The surface tension is gorgeously illustrated in this shot.  Killer image, Karen.  Congrats on the ribbon!</td>', 'The surface tension is gorgeously illustrated in this shot.  Killer image, Karen.  Congrats on the ribbon!', '2011-07-26 13:05:29.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6481466, 962716, 96751, '<td valign="top">Congrats on the ribbon and the 1x, Christophe.  The colors here are extraordinary.  Sort of like a peacock on acid.</td>', 'Congrats on the ribbon and the 1x, Christophe.  The colors here are extraordinary.  Sort of like a peacock on acid.', '2011-07-26 13:06:32.000000', NULL, 0),
(6481468, 962468, 96751, '<td valign="top">What Deb said.  When planets collide.  Love the golden tones.</td>', 'What Deb said.  When planets collide.  Love the golden tones.', '2011-07-26 13:09:15.000000', NULL, 0),
(6481470, 962636, 96751, '<td valign="top">Divine, Irene!  An igloo!!!  Those colors are breathtaking.  I''m very curious about the "moat" around the bubble, though.</td>', 'Divine, Irene!  An igloo!!!  Those colors are breathtaking.  I''m very curious about the "moat" around the bubble, though.', '2011-07-26 13:11:11.000000', NULL, 0),
(6481471, 962704, 96751, '<td valign="top">So, by my counts, there are only 2 challenges where you didn''t make top 10, Jenn!  You are just awesome.  Congrats on yet another top 10.</td>', 'So, by my counts, there are only 2 challenges where you didn''t make top 10, Jenn!  You are just awesome.  Congrats on yet another top 10.', '2011-07-26 13:12:51.000000', NULL, 0),
(6481472, 962741, 96751, '<td valign="top">Very exotic :-)</td>', 'Very exotic :-)', '2011-07-26 13:13:51.000000', NULL, 0),
(6481473, 962403, 96751, '<td valign="top">Fascinating image.  Totally OOB macro, and beautifully pp''d.  Congrats on the top 10.</td>', 'Fascinating image.  Totally OOB macro, and beautifully pp''d.  Congrats on the top 10.', '2011-07-26 13:14:43.000000', NULL, 0),
(6481475, 962826, 114969, '<td valign="top">Congratulations William, the bubble is a refreshing addition to the concept: it''s the first time I see a soap bubble next to a droplets collision. Also, given your explanations on the timing, I''m sure it required a good amount of work and patience :-)<br/>May I ask what hardware you used for the droplets? Some kind of micro-controller commanding a solenoid valve I suppose?</td>', 'Congratulations William, the bubble is a refreshing addition to the concept: it''s the first time I see a soap bubble next to a droplets collision. Also, given your explanations on the timing, I''m sure it required a good amount of work and patience :-)May I ask what hardware you used for the droplets? Some kind of micro-controller commanding a solenoid valve I suppose?', '2011-07-26 13:14:56.000000', NULL, 0),
(6481476, 962463, 96751, '<td valign="top">Just shot one of these this weekend!  With a camera.  Just to clarify :-)  Gorgeous birds.  Mine recited Shakespeare.</td>', 'Just shot one of these this weekend!  With a camera.  Just to clarify :-)  Gorgeous birds.  Mine recited Shakespeare.', '2011-07-26 13:16:47.000000', NULL, 0),
(6481478, 962027, 96751, '<td valign="top">That eye is incredible.  (I think your white balance is the "issue".)</td>', 'That eye is incredible.  (I think your white balance is the "issue".)', '2011-07-26 13:18:18.000000', NULL, 0),
(6481479, 962825, 96751, '<td valign="top">Ooooh, original take on the refraction drops.  LOVE it.  Very Dali.</td>', 'Ooooh, original take on the refraction drops.  LOVE it.  Very Dali.', '2011-07-26 13:19:11.000000', NULL, 0),
(6481482, 962357, 114969, '<td valign="top">Congratulations on your ribbon Karen :-) I love the lighting work on this one, I suspect it is not easy to achieve as it looks. I''d say you used a window and blinds for the patterns, and a softbox for added light on the paper clip, am I about right?</td>', 'Congratulations on your ribbon Karen :-) I love the lighting work on this one, I suspect it is not easy to achieve as it looks. I''d say you used a window and blinds for the patterns, and a softbox for added light on the paper clip, am I about right?', '2011-07-26 13:20:46.000000', NULL, 0),
(6481487, 962074, 96751, '<td valign="top">Epic lighting!</td>', 'Epic lighting!', '2011-07-26 13:38:10.000000', NULL, 0),
(6481490, 962796, 96751, '<td valign="top">Pretty good, Spiff!  Fabulous colors and pattern.</td>', 'Pretty good, Spiff!  Fabulous colors and pattern.', '2011-07-26 13:41:50.000000', NULL, 0),
(6481491, 962815, 96751, '<td valign="top">LOVE IT!!!!!  Cats have the cutest noses.</td>', 'LOVE IT!!!!!  Cats have the cutest noses.', '2011-07-26 13:43:38.000000', NULL, 0),
(6481493, 962764, 96751, '<td valign="top">Well, I like it.  Would also have worked for painting with light.</td>', 'Well, I like it.  Would also have worked for painting with light.', '2011-07-26 13:46:35.000000', NULL, 0),
(6481494, 962791, 96751, '<td valign="top">Do these make you shrink, or grow?</td>', 'Do these make you shrink, or grow?', '2011-07-26 13:48:12.000000', NULL, 0),
(6481495, 962633, 96751, '<td valign="top">Whatever you did, the results are fascinating!</td>', 'Whatever you did, the results are fascinating!', '2011-07-26 13:49:36.000000', NULL, 0),
(6481496, 962042, 96751, '<td valign="top">The non-eye drops look reptilian!!</td>', 'The non-eye drops look reptilian!!', '2011-07-26 13:50:53.000000', NULL, 0),
(6481497, 962619, 96751, '<td valign="top">TOTALLY creeped me out, Bear!!!  While the full slice was breathtaking, this looks like a bloody mouthful!  Awesome.</td>', 'TOTALLY creeped me out, Bear!!!  While the full slice was breathtaking, this looks like a bloody mouthful!  Awesome.', '2011-07-26 13:51:54.000000', NULL, 0),
(6481498, 962592, 96751, '<td valign="top">I thought, from the thumb, these were earrings!  Lovely macro, Anita.</td>', 'I thought, from the thumb, these were earrings!  Lovely macro, Anita.', '2011-07-26 13:52:34.000000', NULL, 0),
(6481500, 962388, 96751, '<td valign="top">And a giant turtle in the left foreground.  Brilliant image, Colleen!</td>', 'And a giant turtle in the left foreground.  Brilliant image, Colleen!', '2011-07-26 13:54:13.000000', NULL, 0),
(6481501, 962742, 96751, '<td valign="top">This was a very happy challenge for kitty lovers :-)</td>', 'This was a very happy challenge for kitty lovers :-)', '2011-07-26 13:56:04.000000', NULL, 0),
(6481502, 962632, 96751, '<td valign="top">Irises are SO bizarre.</td>', 'Irises are SO bizarre.', '2011-07-26 13:57:00.000000', NULL, 0),
(6481503, 962826, 59267, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by gyaban:</b></div><hr/><i> Congratulations William, the bubble is a refreshing addition to the concept: it''s the first time I see a soap bubble next to a droplets collision. Also, given your explanations on the timing, I''m sure it required a good amount of work and patience :-)<br/>May I ask what hardware you used for the droplets? Some kind of micro-controller commanding a solenoid valve I suppose? </i></td></tr></table> <br/>I never mentioned my dropper because what a shame I am still using the old fashion method. I still wonder if it worth upgrading to DIY digital micro controller like you said. Especially after I saw people contaminated my "Absolut fulfilling" thread like that. I guess I won''t do it unless I feel so much fun doing the soldering work and electrical engineering research.</td>', 'Originally posted by gyaban: Congratulations William, the bubble is a refreshing addition to the concept: it''s the first time I see a soap bubble next to a droplets collision. Also, given your explanations on the timing, I''m sure it required a good amount of work and patience :-)May I ask what hardware you used for the droplets? Some kind of micro-controller commanding a solenoid valve I suppose?  I never mentioned my dropper because what a shame I am still using the old fashion method. I still wonder if it worth upgrading to DIY digital micro controller like you said. Especially after I saw people contaminated my "Absolut fulfilling" thread like that. I guess I won''t do it unless I feel so much fun doing the soldering work and electrical engineering research.', '2011-07-26 13:57:39.000000', NULL, 0),
(6481504, 962462, 96751, '<td valign="top">I love the disrespect of the garish colors defying the solemnity of the wall.</td>', 'I love the disrespect of the garish colors defying the solemnity of the wall.', '2011-07-26 13:58:32.000000', NULL, 0),
